public interface MinimumSpanningTreeAlgorithm {
    MstResult find(WeightedGraph graph);

    default MstResult find(int vertexCount, int[][] edgeRows) {
        return find(WeightedGraphs.fromEdgeRows(vertexCount, edgeRows));
    }

    default MstResult find(int vertexCount, List<Edge> edges) {
        return find(WeightedGraphs.fromEdges(vertexCount, edges));
    }
}

public final class DisjointSet {
    private final int[] parent;
    private final int[] rank;

    public DisjointSet(int size) {
        if (size < 0) {
            throw new IllegalArgumentException("Set size cannot be negative.");
        }

        parent = new int[size];
        rank = new int[size];

        for (int vertex = 0; vertex < size; vertex++) {
            parent[vertex] = vertex;
            rank[vertex] = 1;
        }
    }

    public boolean unionIfSeparate(int first, int second) {
        int firstRoot = find(first);
        int secondRoot = find(second);

        if (firstRoot == secondRoot) {
            return false;
        }

        if (rank[firstRoot] < rank[secondRoot]) {
            parent[firstRoot] = secondRoot;
        } else if (rank[firstRoot] > rank[secondRoot]) {
            parent[secondRoot] = firstRoot;
        } else {
            parent[secondRoot] = firstRoot;
            rank[firstRoot]++;
        }

        return true;
    }

    private int find(int vertex) {
        if (parent[vertex] != vertex) {
            parent[vertex] = find(parent[vertex]);
        }

        return parent[vertex];
    }
}

import java.util.ArrayList;
import java.util.List;

public final class KruskalMinimumSpanningTree implements MinimumSpanningTreeAlgorithm {
    @Override
    public MstResult find(WeightedGraph graph) {
        SelectionTracker tracker = new SelectionTracker(graph.requiredEdgeCount());
        DisjointSet disjointSet = new DisjointSet(graph.vertexCount());

        for (Edge edge : graph.edgesSortedByWeight()) {
            if (!disjointSet.unionIfSeparate(edge.from(), edge.to())) {
                continue;
            }

            tracker.include(edge);
            if (tracker.isComplete()) {
                break;
            }
        }

        return tracker.toResult();
    }

    private static final class SelectionTracker {
        private final int targetEdgeCount;
        private final List<Edge> selectedEdges;
        private int totalWeight;

        private SelectionTracker(int targetEdgeCount) {
            this.targetEdgeCount = targetEdgeCount;
            selectedEdges = new ArrayList<>(targetEdgeCount);
        }

        private void include(Edge edge) {
            selectedEdges.add(edge);
            totalWeight += edge.weight();
        }

        private boolean isComplete() {
            return selectedEdges.size() == targetEdgeCount;
        }

        private MstResult toResult() {
            return new MstResult(totalWeight, selectedEdges, isComplete());
        }
    }
}

